// Bento 4 — the whole section as one drop-in component: heading, the four
// cards, their dashed frames and icon bloom.
//
// The wide Web Design hero sits over the Clean Code + Accelerate pair on the
// left; Future Forward (tall) anchors the right. The row stretches so both
// sides share one height. Entrance is a subtle staggered rise.
//
// Heading is overridable so the section can be reused with different copy;
// pass `heading={null}` to drop it and use your own.

import WebDesignCard from "./bento-04/web-design-card"
import FutureForwardCard from "./bento-04/future-forward-card"
import CleanCodeCard from "./bento-04/clean-code-card"
import AccelerateCard from "./bento-04/accelerate-card"
import DottedFrame from "./bento-04/dotted-frame"
import IconHolo from "./bento-04/icon-holo"
import "./bento-04/bento-04.css"

const rise = "b4-rise"

// `b4-card` scopes the hover: it brightens the dashed frame (see dotted-frame)
// and blooms the icon (see bento-04.css). Each card carries its own gradient id
// in --b4-holo, so hovering one never recolours the others.
const card = `relative b4-card ${rise}`

const cardProps = (id: string, delay: number) => ({
    className: card,
    style: { animationDelay: `${delay}ms`, "--b4-holo": `url(#${id})` } as React.CSSProperties,
})

export default function Bento4({
    heading = "Built for teams that ship",
    subheading = "Design, code and speed in one system, so every idea reaches production looking exactly the way you imagined it.",
    className = "",
}: {
    heading?: React.ReactNode
    subheading?: React.ReactNode
    className?: string
}) {
    return (
        <div className={`flex flex-col items-center gap-12 ${className}`}>
            {heading !== null && (
                <header className={`max-w-2xl text-center ${rise}`}>
                    {/* Same vertical clip-text gradient as the card titles, mirrored for light. */}
                    <h2 className="bg-gradient-to-b from-[#18181B] to-[#71717A] bg-clip-text text-4xl font-semibold tracking-tight text-transparent dark:from-[#F9FAFB] dark:to-[#949495]">
                        {heading}
                    </h2>
                    {subheading !== null && (
                        <p className="mt-3 text-base text-zinc-500 dark:text-zinc-400">{subheading}</p>
                    )}
                </header>
            )}

            <div className="flex items-stretch gap-9">
                {/* Left column: wide hero over a pair of medium cards */}
                <div className="flex w-[665px] max-w-full flex-col gap-9">
                    <div {...cardProps("holo-web", 0)}>
                        <DottedFrame id="holo-web" />
                        <IconHolo id="holo-web" />
                        <WebDesignCard />
                    </div>
                    <div className="flex min-h-0 flex-1 gap-9">
                        <div {...cardProps("holo-clean", 120)} className={`${card} flex-1`}>
                            <DottedFrame id="holo-clean" />
                            <IconHolo id="holo-clean" />
                            <CleanCodeCard />
                        </div>
                        <div {...cardProps("holo-accel", 180)} className={`${card} flex-1`}>
                            <DottedFrame id="holo-accel" />
                            <IconHolo id="holo-accel" />
                            <AccelerateCard />
                        </div>
                    </div>
                </div>

                {/* Right: tall anchor, matched to the left column height */}
                <div {...cardProps("holo-future", 60)} className={`${card} w-[348px]`}>
                    <DottedFrame id="holo-future" />
                    <IconHolo id="holo-future" />
                    <FutureForwardCard />
                </div>
            </div>
        </div>
    )
}

// Web Design & Development card — faithful to the Figma reference (665×266).
// Left: blue code-window icon tile, gradient title, muted subtitle.
// Right: a clipped "screen" panel — a horizontal gold→blue gradient wash under
// 6 faint gradient columns, a cream→blue centered label, and gold "12"/"H"
// annotation marks. Static, pixel-positioned to match the export.

const ACCENT = "#41A4D2"

// 6 vertical column strips inside the inner panel (x offset 9, pitch 55, width 43).
const COLS = [9, 64, 119, 174, 229, 284]

export default function WebDesignCard() {
    return (
        <div className="group relative h-[266px] w-full max-w-full overflow-hidden rounded-2xl bg-[var(--b4-surface)]">
            {/* Outline as a top-most overlay, not a `border` on the card itself:
                the screen panel below overhangs the card's right and bottom
                edges, and a real border paints *under* children — it vanished
                exactly there. */}
            <div className="pointer-events-none absolute inset-0 z-10 rounded-2xl border border-[var(--b4-border)]" />

            {/* Left column */}
            <div className="absolute left-5 top-[55px] w-[250px]">
                {/* Code-window icon tile */}
                <div className="grid h-14 w-14 place-items-center rounded-full border border-[var(--b4-border)] bg-[var(--b4-tile)]">
                    {/* Shared metric across the four cards: ~19px glyph, ~2.2px
                        stroke. This one is authored at 18 units and fills its box
                        edge to edge, so it's drawn at 18.9 (scale 1.05) and 2.1
                        lands the stroke on 2.2. */}
                    <svg width="18.9" height="18.9" viewBox="0 0 18 18" fill="none" className="overflow-visible" aria-hidden>
                        <path
                            d="M7 6.5L5 9L7 11.5M11 6.5L13 9L11 11.5M2 0H16C17.1046 0 18 0.8954 18 2V16C18 17.1046 17.1046 18 16 18H2C0.8954 18 0 17.1046 0 16V2C0 0.8954 0.8954 0 2 0Z"
                            stroke={ACCENT}
                            strokeWidth={2.1}
                            strokeLinecap="round"
                            strokeLinejoin="round"
                        />
                    </svg>
                </div>

                <h3 className="mt-[17px] bg-gradient-to-b from-[var(--b4-title-from)] to-[var(--b4-title-to)] bg-clip-text text-[18px] font-semibold leading-tight text-transparent">
                    Web Design &amp; Development
                </h3>
                <p className="mt-2 text-[13px] leading-relaxed text-[var(--b4-body)]">
                    We create visually appealing and functional websites that
                    captivate your audience and drive results.
                </p>
            </div>

            {/* Right "screen" panel — clipped at the card's bottom edge */}
            <div className="absolute left-[291px] top-[50px] h-[272px] w-[354px] rounded-xl bg-[var(--b4-scr-bezel)] ring-1 ring-inset ring-[var(--b4-scr-line)]">
                {/* "12" dimension mark: gold H-line whose verticals sit on the column stripes (inner-x 52/64) */}
                <div className="absolute -top-[9px] left-[60px]">
                    <span className="relative block h-[18px] w-[12px]">
                        <span className="absolute inset-y-0 left-0 w-px bg-[var(--b4-mark)] opacity-80" />
                        <span className="absolute inset-y-0 right-0 w-px bg-[var(--b4-mark)] opacity-80" />
                        <span className="absolute inset-x-0 top-1/2 h-px -translate-y-1/2 bg-[var(--b4-mark)] opacity-80" />
                    </span>
                    <span
                        className="absolute -top-[15px] left-1/2 -translate-x-1/2 whitespace-nowrap text-[11px] font-medium leading-none"
                        style={{ color: "var(--b4-mark)" }}
                    >
                        12
                    </span>
                </div>

                {/* Inner recessed panel */}
                <div className="absolute inset-2 overflow-hidden rounded-lg bg-[var(--b4-scr-inner)] ring-1 ring-inset ring-[var(--b4-scr-line)]">
                    {/* Horizontal gold → blue gradient wash (under the columns) */}
                    <div
                        className="absolute inset-0 opacity-35 transition-opacity duration-500 group-hover:opacity-[var(--b4-scr-wash-opacity)]"
                        style={{ background: "var(--b4-scr-wash)" }}
                    />

                    {/* Faint gradient columns */}
                    {COLS.map((x) => (
                        <div
                            key={x}
                            className="absolute top-0 h-full w-[43px] border-x"
                            style={{
                                left: x,
                                borderColor: "rgba(255,255,255,0.06)",
                                background:
                                    "linear-gradient(180deg, rgba(255,255,255,0.105), rgba(255,255,255,0.022))",
                            }}
                        />
                    ))}

                    {/* Centered label */}
                    <p className="absolute left-1/2 top-[44%] max-w-[190px] -translate-x-1/2 -translate-y-1/2 bg-gradient-to-r from-[var(--b4-scr-text-from)] to-[var(--b4-scr-text-to)] bg-clip-text text-center text-[15px] font-medium text-transparent opacity-90">
                        Website that delivers a unique
                    </p>
                </div>
            </div>
        </div>
    )
}

"use client"

// Clean Code — converted from the Figma SVG export to a real React component.
// Vector text is now selectable HTML; the code icon and syntax-highlighted
// snippet are the only genuinely-graphical bits. This card's typography is the
// reference for the whole bento: gradient heading + #7B7B7B body.

import { Fragment, useRef } from "react"
import gsap from "gsap"
import { useGSAP } from "@gsap/react"
import { ScrambleTextPlugin } from "gsap/ScrambleTextPlugin"

gsap.registerPlugin(useGSAP, ScrambleTextPlugin)

// The snippet as data — each line a list of [text, colour] tokens. One copy in
// the DOM: it rests grey and, on hover, each token scrambles in place while its
// colour lands, so the snippet resolves from grey to syntax-coloured.
const LINES: [string, string][][] = [
    [
        ["import ", "#6B7280"],
        ["{ ", "#6B7280"],
        ["ClassValue, clsx", "#34D399"],
        [" }", "#6B7280"],
        [" from ", "#6B7280"],
        ['"clsx"', "#FCD34D"],
    ],
    [
        ["import ", "#6B7280"],
        ["{ ", "#6B7280"],
        ["twMerge", "#34D399"],
        [" }", "#6B7280"],
        [" from ", "#6B7280"],
        ['"tailwind-merge"', "#FCD34D"],
    ],
    [
        ["export ", "#F87171"],
        ["{ ", "#6B7280"],
        ["twMerge", "#34D399"],
        [" }", "#6B7280"],
        [" from ", "#6B7280"],
        ['"tailwind-merge"', "#FCD34D"],
    ],
]

const GREY = "#6B7280"
const SCRAMBLE = 0.16 // per token
const STAGGER = 0.015 // between tokens, in DOM order — reads as line-by-line

const tokens = (line: [string, string][]) =>
    line.map(([text, color], i) => (
        <span key={i} data-color={color} style={{ color: GREY }}>
            {text}
        </span>
    ))

export default function CleanCodeCard() {
    const root = useRef<HTMLDivElement>(null)

    useGSAP(
        () => {
            const card = root.current!
            const spans = card.querySelectorAll<HTMLSpanElement>("code span[data-color]")
            const reduce = window.matchMedia("(prefers-reduced-motion: reduce)").matches

            // Freeze the snippet box at its resting size so nothing reflows
            // while the tokens are scrambling.
            // Measured after fonts settle — a mono swap mid-load would otherwise
            // freeze the fallback's metrics.
            const pre = card.querySelector("pre")!
            document.fonts.ready.then(() => gsap.set(pre, { width: pre.offsetWidth, height: pre.offsetHeight }))

            // Paused timeline played on enter / reversed on leave, so an
            // interrupted hover rewinds from wherever it got to.
            const tl = gsap.timeline({ paused: true })
            spans.forEach((span, i) => {
                tl.to(
                    span,
                    {
                        color: span.dataset.color,
                        duration: reduce ? 0.2 : SCRAMBLE,
                        ease: "none",
                        ...(reduce
                            ? {}
                            : { scrambleText: { text: span.textContent!, chars: "01<>/{}", speed: 1 } }),
                    },
                    reduce ? 0 : i * STAGGER,
                )
            })

            const enter = () => tl.play()
            const leave = () => tl.reverse()
            card.addEventListener("pointerenter", enter)
            card.addEventListener("pointerleave", leave)
            return () => {
                card.removeEventListener("pointerenter", enter)
                card.removeEventListener("pointerleave", leave)
            }
        },
        { scope: root },
    )

    return (
        <div
            ref={root}
            className="group relative flex h-full min-h-[230px] w-full flex-col overflow-hidden rounded-2xl border border-[var(--b4-border)] bg-[var(--b4-surface)] p-5"
        >
            <div className="flex items-start justify-between gap-4">
                {/* Code-window icon tile */}
                <div className="grid h-14 w-14 shrink-0 place-items-center rounded-full border border-[var(--b4-border)] bg-[var(--b4-tile)]">
                    {/* 22-unit square viewBox centred on the glyph (bbox 38–58 x,
                        57–73 y). The old 30×22 box was non-square, so `meet` shrank
                        the whole icon — and its stroke — to 0.8×. */}
                    <svg width="21.6" height="21.6" viewBox="37 54 22 22" fill="none" className="overflow-visible" aria-hidden>
                        <path
                            d="M54 69L58 65L54 61M42 61L38 65L42 69M50.5 57L45.5 73"
                            stroke="#41A4D2"
                            strokeWidth={2.2}
                            strokeLinecap="round"
                            strokeLinejoin="round"
                        />
                    </svg>
                </div>

                {/* Faint syntax-highlighted snippet */}
                <pre
                    aria-hidden
                    className="mt-1 select-none overflow-hidden font-mono text-[10px] leading-[1.7] opacity-75 transition-opacity duration-200 ease-out group-hover:opacity-100"
                >
                    <code>
                        {LINES.map((line, i) => (
                            <Fragment key={i}>
                                {i > 0 && "\n"}
                                <span className="inline-block whitespace-nowrap">{tokens(line)}</span>
                            </Fragment>
                        ))}
                    </code>
                </pre>
            </div>

            <h3 className="mt-[17px] bg-gradient-to-b from-[var(--b4-title-from)] to-[var(--b4-title-to)] bg-clip-text text-[18px] font-semibold leading-tight text-transparent">
                Clean Code
            </h3>
            <p className="mt-2 max-w-[300px] text-[13px] leading-relaxed text-[var(--b4-body)]">
                our expertise in advanced coding techniques, we ensure your digital
                projects are delivered on time and surpass your expectations
            </p>
        </div>
    )
}

"use client"

// Dashed blueprint frame — 1px dashed lines (dash 4 / gap 4) 8px outside the
// parent on all sides. Parent must be `relative`.
//
// Each line runs the full svg span and overshoots the frame box by OVER on both
// ends, so perpendicular lines cross into a `+` at every corner instead of
// stopping short of each other.
//
// Each side is gradiented independently along its own length, symmetric about
// its midpoint: brightest at the center, fading out only across the overshoot
// tails so the corners themselves stay lit.
import { useRef } from "react"
import gsap from "gsap"
import { useGSAP } from "@gsap/react"

gsap.registerPlugin(useGSAP)

const OVER = 26

// One dash period (4 + 4). Shifting the offset by exactly this loops seamlessly.
const PERIOD = 8
const CYCLE = 0.6

// Themed in bento-04.css (.b4-card): dark mode fades up from near-black, light
// mode fades down from near-white, so the dashes stay a whisper against the
// page either way instead of a hard outline.
const STOPS: [string, string][] = [
    ["0%", "var(--b4-dash-tail)"],
    ["6%", "var(--b4-dash-mid)"],
    ["50%", "var(--b4-dash-peak)"],
    ["94%", "var(--b4-dash-mid)"],
    ["100%", "var(--b4-dash-tail)"],
]

// Lines span 0→100% of the (overshot) svg; `transform` pulls the far edges back
// in by OVER, since SVG attributes can't express `100% - 14px`.
const LINES = [
    { k: "top", x1: "0", y1: OVER, x2: "100%", y2: OVER, g: "h", t: undefined },
    { k: "bottom", x1: "0", y1: "100%", x2: "100%", y2: "100%", g: "h", t: `translate(0,${-OVER})` },
    { k: "left", x1: OVER, y1: "0", x2: OVER, y2: "100%", g: "v", t: undefined },
    { k: "right", x1: "100%", y1: "0", x2: "100%", y2: "100%", g: "v", t: `translate(${-OVER},0)` },
] as const

// `id` must be unique per card: the gradients are userSpaceOnUse, so a shared id
// would make every frame resolve against the first card's box.
export default function DottedFrame({ id }: { id: string }) {
    const h = `${id}-h`
    const v = `${id}-v`
    const root = useRef<SVGSVGElement>(null)

    // Marching dashes on hover: horizontals run right, verticals run up. Both
    // lines of a pair are drawn in the same direction (h: left→right, v:
    // top→bottom), so one signed offset per axis is enough.
    useGSAP(
        () => {
            const card = root.current?.closest(".b4-card")
            if (!card) return

            const march = (axis: string, to: number) =>
                gsap.to(root.current!.querySelectorAll(`[data-axis="${axis}"]`), {
                    strokeDashoffset: to,
                    duration: CYCLE,
                    ease: "none",
                    repeat: -1,
                    paused: true,
                })

            // Two tweens, not one timeline: they only ever run together, and a
            // shared repeat would still need per-axis targets anyway.
            const tweens = [march("h", -PERIOD), march("v", PERIOD)]
            const enter = () => tweens.forEach((t) => t.play())
            // Pause, not kill — resuming mid-cycle avoids a snap on re-hover.
            const leave = () => tweens.forEach((t) => t.pause())
            card.addEventListener("pointerenter", enter)
            card.addEventListener("pointerleave", leave)
            return () => {
                card.removeEventListener("pointerenter", enter)
                card.removeEventListener("pointerleave", leave)
            }
        },
        { scope: root },
    )

    return (
        <svg
            ref={root}
            aria-hidden
            className="pointer-events-none absolute -left-[34px] -top-[34px] h-[calc(100%+68px)] w-[calc(100%+68px)] overflow-visible opacity-70 transition-opacity duration-500 [.b4-card:hover_&]:opacity-100"
        >
            <defs>
                <linearGradient id={h} gradientUnits="userSpaceOnUse" x1="0%" y1="0" x2="100%" y2="0">
                    {STOPS.map(([o, c]) => (
                        <stop key={o} offset={o} stopColor={c} />
                    ))}
                </linearGradient>
                <linearGradient id={v} gradientUnits="userSpaceOnUse" x1="0" y1="0%" x2="0" y2="100%">
                    {STOPS.map(([o, c]) => (
                        <stop key={o} offset={o} stopColor={c} />
                    ))}
                </linearGradient>
            </defs>
            {LINES.map((l) => (
                <line
                    key={l.k}
                    data-axis={l.g}
                    x1={l.x1}
                    y1={l.y1}
                    x2={l.x2}
                    y2={l.y2}
                    transform={l.t}
                    stroke={`url(#${l.g === "h" ? h : v})`}
                    strokeWidth={1}
                    strokeDasharray="4 4"
                    strokeLinecap="butt"
                />
            ))}
        </svg>
    )
}

"use client"

// Chromatic icon hover for the Bento 04 cards. Renders one private gradient per
// card; the card wrapper points its icons at it via --b4-holo (bento-04.css),
// and GSAP blooms the stops from the resting blue out to the D2 holographic
// palette on hover.
//
// Only `stop-color` is animated here. `stroke` stays pinned to this gradient —
// a paint server (`url(#…)`) is not an interpolatable value, so swapping stroke
// between two paints snaps no matter what drives it.

import { useRef } from "react"
import gsap from "gsap"
import { useGSAP } from "@gsap/react"

gsap.registerPlugin(useGSAP)

const BASE = "#41A4D2"
const BRAND = ["#56DAFF", "#A8FF80", "#FFF4A3", "#FF9CC8", "#C28AFF", "#56DAFF"]
const OFFSETS = ["0%", "22%", "42%", "62%", "82%", "100%"]

const DURATION = 0.35
const STAGGER = 0.035

export default function IconHolo({ id }: { id: string }) {
    const root = useRef<SVGSVGElement>(null)

    useGSAP(
        () => {
            const card = root.current?.closest(".b4-card")
            if (!card) return

            // One paused timeline played forwards on enter and reversed on
            // leave, so the bloom retreats the way it arrived and an
            // interrupted hover rewinds from wherever it got to.
            const stops = root.current!.querySelectorAll("stop")
            const tl = gsap.timeline({ paused: true })
            stops.forEach((stop, i) => {
                tl.to(stop, { attr: { "stop-color": BRAND[i] }, duration: DURATION, ease: "power2.inOut" }, i * STAGGER)
            })

            const enter = () => tl.play()
            const leave = () => tl.reverse()
            card.addEventListener("pointerenter", enter)
            card.addEventListener("pointerleave", leave)
            return () => {
                card.removeEventListener("pointerenter", enter)
                card.removeEventListener("pointerleave", leave)
            }
        },
        { scope: root },
    )

    return (
        <svg ref={root} aria-hidden width="0" height="0" className="absolute">
            <defs>
                <linearGradient id={id} className="b4-holo" x1="0" y1="0" x2="1" y2="1">
                    {OFFSETS.map((o) => (
                        <stop key={o} offset={o} stopColor={BASE} />
                    ))}
                </linearGradient>
            </defs>
        </svg>
    )
}

/* Bento 04 — card chrome palette, icon-bloom paint hookup and the Future
   Forward marquee. Everything else in the block is Tailwind or inline SVG.
   Scoped to .b4-card, so it only ever touches this block. */


/* ── Bento-4 card hover ──────────────────────────────────────────────────────
   Each card renders its own gradient (<IconHolo />) and points its icons at it
   through --b4-holo, so hovering one card never recolours another.

   The stop-colour bloom is driven by GSAP in components/bento-4/icon-holo —
   deliberately not duplicated here, since it writes the stops directly and a
   :hover rule would be driving the same property. Only the paint reference and
   the glow live in CSS. */
.b4-card [stroke="#41A4D2"] {
  stroke: var(--b4-holo);
  transition: filter 400ms cubic-bezier(0.33, 1, 0.68, 1); /* power2.out */
}
.b4-card:hover [stroke="#41A4D2"] {
  filter: drop-shadow(0 0 6px rgba(168, 255, 128, 0.4));
}

/* Light theme: the holographic stops are pastels picked to glow on a near-black
   tile — against the light tile they blow out. Dimmed with a filter rather than
   a second palette, so the hover stays the D2 brand gradient (just less lit) and
   the GSAP bloom keeps writing one set of stops. */
html:not(.dark) .b4-card [stroke="#41A4D2"] {
  filter: brightness(0.78) saturate(1.3);
}
html:not(.dark) .b4-card:hover [stroke="#41A4D2"] {
  filter: brightness(0.78) saturate(1.3) drop-shadow(0 0 6px rgba(120, 200, 90, 0.35));
}

@media (prefers-reduced-motion: reduce) {
  .b4-card:hover [stroke="#41A4D2"] {
    filter: none;
  }
  html:not(.dark) .b4-card:hover [stroke="#41A4D2"] {
    filter: brightness(0.78) saturate(1.3);
  }
}

/* ── Bento-4 palette ─────────────────────────────────────────────────────────
   Card *chrome* only — surface, border, icon tile, type. Dark is the Figma
   reference; light mirrors it. Vars (not `dark:` classes) because half these
   colours land on raw SVG `fill=`/`stroke=` attributes, which Tailwind variants
   can't reach.

   Deliberately NOT themed: the "screen" panel in Web Design and the terminal in
   Future Forward. Those read as devices — a lit display stays dark in both
   themes, and their gold/blue washes are tuned for it. */
.b4-card {
  --b4-surface: #ffffff;
  --b4-border: #e4e4e7;
  --b4-tile: #f4f4f5;
  --b4-title-from: #18181b;
  --b4-title-to: #71717a;
  --b4-body: #71717a;
  --b4-hairline: rgba(10, 10, 10, 0.12);
  --b4-rings: #f4f4f4;
  --b4-label-from: #3f3f46;
  --b4-label-to: #71717a;
  --b4-glow: rgba(76, 210, 65, 0.18);
  --b4-dash-tail: oklch(0.925 0 0);
  --b4-dash-mid: oklch(0.785 0.006 17.5);
  --b4-dash-peak: oklch(0.625 0.011 17.5);
  --b4-scr-bezel: rgba(233, 233, 236, 0.15);
  --b4-scr-inner: rgba(120, 118, 125, 0.14);
  --b4-scr-line: rgba(132, 132, 140, 0.15);
  --b4-mark: #c9a800;
  --b4-scr-text-from: #fff2dc;
  --b4-scr-text-to: #b6e1ff;
  --b4-scr-wash: linear-gradient(90deg, #e0a800, #1f74cf);
  --b4-scr-wash-opacity: 0.6;
}
.dark .b4-card {
  --b4-surface: #151313;
  --b4-border: #342f2f;
  --b4-tile: #1e1e1f;
  --b4-title-from: #f9fafb;
  --b4-title-to: #949495;
  --b4-body: #7b7b7b;
  --b4-hairline: rgba(255, 239, 239, 0.15);
  --b4-rings: #1f1e1e;
  --b4-label-from: #f9f9f9;
  --b4-label-to: #c8c8c8;
  --b4-glow: rgba(50, 65, 45, 0.36);
  --b4-dash-tail: oklch(0.217 0.005 17.5);
  --b4-dash-mid: oklch(0.393 0.008 17.5);
  --b4-dash-peak: oklch(0.611 0.011 17.5);
  --b4-scr-bezel: rgba(10, 10, 10, 0.15);
  --b4-scr-inner: rgba(94, 93, 96, 0.3);
  --b4-scr-line: rgba(255, 239, 239, 0.15);
  --b4-mark: #f2d271;
  --b4-scr-text-from: #fff2dc;
  --b4-scr-text-to: #b6e1ff;
  --b4-scr-wash: linear-gradient(90deg, #7d5608, #307bbc);
  --b4-scr-wash-opacity: 0.6;
}

/* Bento-4 Future Forward — pill rows marquee left/right/left on card hover:
   one direction forever, a pill exiting one edge re-entering the other. Each
   row renders its pill tile twice; --b4-shift is exactly one tile, so at the
   end of a cycle the duplicate lands where the original started and the reset
   is invisible. The svg row moves in viewBox user units, the DOM label row in
   % of the card width — same distance, so they stay locked at any card size. */
@keyframes b4-marquee {
  to {
    transform: translateX(var(--b4-shift));
  }
}
/* Idle speed. Hover speeds the rows up by ramping each animation's
   playbackRate (see future-forward-card.tsx) rather than swapping
   animation-duration — swapping duration keeps elapsed time, not progress, so
   the row would jump. Ramping the rate is also what damps the pick-up and the
   settle back down. */
.b4-ff-row {
  animation: b4-marquee var(--b4-dur-idle) linear infinite;
}
@media (prefers-reduced-motion: reduce) {
  .b4-ff-row {
    animation: none;
  }
}

/* Entrance — a short staggered rise per card (delay is set inline). Named
   locally so the block carries its own keyframes instead of relying on the
   host app's animation utilities. */
@keyframes b4-rise {
  0% {
    opacity: 0;
    transform: translateY(8px);
  }
  100% {
    opacity: 1;
    transform: translateY(0);
  }
}
.b4-rise {
  opacity: 0;
  animation: b4-rise 480ms cubic-bezier(0.22, 1, 0.36, 1) forwards;
}
@media (prefers-reduced-motion: reduce) {
  .b4-rise {
    opacity: 1;
    animation: none;
  }
}
